import type { Plugin } from '../plugin-definition/plugin-definition.ts'
import { choiceValue, type PluginOption } from '../plugin-definition/plugin-option.ts'
import { CONFIG_MODULE } from './project-paths.ts'

const HEADER = [
  '// Generated by create-next-suite: the plugins next-suite.config.ts can name. Do not edit;',
  '// it is written anew whenever the project is generated.',
]
const IDENTIFIER = /^[A-Za-z_$][\w$]*$/
const NO_ANSWERS = 'Record<never, never>'
const ENTRY_INDENT = '    '
const ANSWER_INDENT = '      '

const keyOf = (name: string): string => (IDENTIFIER.test(name) ? name : JSON.stringify(name))

/** The type of an option's answer: a boolean, one of the choices or a list of them. */
const answerType = (option: PluginOption): string => {
  if (option.type === 'boolean') {
    return 'boolean'
  }
  const choices = option.choices.map((choice) => JSON.stringify(choiceValue(choice))).join(' | ')
  return option.type === 'multiselect' ? `readonly (${choices})[]` : choices
}

const renderEntry = ({ name, options = {} }: Pick<Plugin, 'name' | 'options'>): string[] => {
  const answers = Object.entries(options)
  if (answers.length === 0) {
    return [`${ENTRY_INDENT}${keyOf(name)}: ${NO_ANSWERS};`]
  }
  return [
    `${ENTRY_INDENT}${keyOf(name)}: {`,
    ...answers.map(([key, option]) => `${ANSWER_INDENT}${keyOf(key)}: ${answerType(option)};`),
    `${ENTRY_INDENT}};`,
  ]
}

/**
 * The text of `.next-suite/types.d.ts`: every plugin a project can name, with the type of each of
 * its answers, added to the `PluginRegistry` of `create-next-suite/config`, sorted by name.
 */
export const renderRegistryTypes = (plugins: readonly Pick<Plugin, 'name' | 'options'>[]): string =>
  [
    ...HEADER,
    'export {};',
    '',
    `declare module ${JSON.stringify(CONFIG_MODULE)} {`,
    '  interface PluginRegistry {',
    ...[...plugins].sort((left, right) => (left.name < right.name ? -1 : 1)).flatMap(renderEntry),
    '  }',
    '}',
    '',
  ].join('\n')
